import itertools

def get_1_factors(n):
    nodes = list(range(n))
    all_pairs = list(itertools.combinations(nodes, 2))

    # Find all possible 1-factors (perfect matchings)
    factors = []
    for combo in itertools.combinations(all_pairs, n // 2):
        # Check if it's a perfect matching
        used_nodes = set()
        is_matching = True
        for p1, p2 in combo:
            if p1 in used_nodes or p2 in used_nodes:
                is_matching = False
                break
            used_nodes.add(p1)
            used_nodes.add(p2)
        if is_matching:
            factors.append(set(combo))
    return factors

def solve_n(n):
    factors = get_1_factors(n)

    # We want to find the smallest a such that there exist a_0, a_1, ..., a_{a-1}
    # factors from the list that are disjoint, and no factor from the list
    # is disjoint from the union of these a factors.
    # This is equivalent to finding a set of a factors whose union's complement
    # contains no factor.

    # Let's try all possible values of a from 1 to n-1
    for a in range(1, n):
        # Check all combinations of a factors
        for combo in itertools.combinations(factors, a):
            # Check if they are all disjoint
            union_edges = set()
            possible = True
            for f in combo:
                if not f.isdisjoint(union_edges):
                    possible = False
                    break
                union_edges.update(f)

            if possible:
                # Check if any factor in the 'factors' list is disjoint from union_edges
                any_factor_left = False
                for f in factors:
                    if f.isdisjoint(union_edges):
                        any_factor_left = True
                        break

                if not any_factor_left:
                    return a
    return None

for n in [4, 6]:
    print(f"n={n}, smallest a={solve_n(n)}")
